function Eyebrow({ children }) {
  return (
    <div style={{ fontFamily: FONTS.body, fontWeight: 700, fontSize: 13, letterSpacing: 2, color: C.blue, textTransform: "uppercase", marginBottom: 10 }}>
      {children}
    </div>
  );
}

function SectionTitle({ children }) {
  return (
    <h2 style={{ fontFamily: FONTS.display, fontWeight: 700, fontSize: "clamp(2.2rem, 4.5vw, 3rem)", color: C.ink, margin: "0 0 28px" }}>
      {children}
      <span style={{ color: C.blue }}>.</span>
    </h2>
  );
}

function Pill({ children, bg = "#fff", border = C.ink, color = C.ink }) {
  return (
    <span
      style={{
        display: "inline-block",
        fontFamily: FONTS.body,
        fontWeight: 600,
        fontSize: 13,
        padding: "7px 16px",
        borderRadius: 999,
        background: bg,
        color,
        border: `2px solid ${border}`,
      }}
    >
      {children}
    </span>
  );
}

function BrutalCard({ children, bg = C.card, style = {}, shadow = SHADOW, className = "" }) {
  return (
    <div
      className={`brutal-card ${className}`}
      style={{
        background: bg,
        border: `2.5px solid ${C.ink}`,
        borderRadius: 18,
        boxShadow: shadow,
        ...style,
      }}
    >
      {children}
    </div>
  );
}

function Reveal({ children, delay = 0, y = 22 }) {
  const ref = React.useRef(null);
  const [shown, setShown] = useState(false);

  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setShown(true);
            io.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.15, rootMargin: "0px 0px -60px 0px" }
    );
    io.observe(node);
    return () => io.disconnect();
  }, []);

  return (
    <div
      ref={ref}
      style={{
        opacity: shown ? 1 : 0,
        transform: shown ? "translateY(0)" : `translateY(${y}px)`,
        transition: `opacity 0.6s ease ${delay}ms, transform 0.6s cubic-bezier(0.22,1,0.36,1) ${delay}ms`,
        willChange: "opacity, transform",
      }}
    >
      {children}
    </div>
  );
}

