/* ────────────────────────────────────────────────────────────
   Styles / layout helpers
   ──────────────────────────────────────────────────────────── */
const styles = {
  wrap: { maxWidth: 1080, margin: "0 auto", padding: "0 24px" },
  section: { padding: "64px 0" },
  body: { fontFamily: FONTS.body, fontSize: 16.5, color: C.inkSoft, lineHeight: 1.75 },
};

/* ────────────────────────────────────────────────────────────
   Root
   ──────────────────────────────────────────────────────────── */
export default function Portfolio() {
  const [active, setActive] = useState("About");

  useEffect(() => {
    const ids = ["about", "skills", "experience", "projects", "contact"];
    const onScroll = () => {
      let current = "About";
      for (const id of ids) {
        const el = document.getElementById(id);
        if (el && el.getBoundingClientRect().top < 140) {
          current = id.charAt(0).toUpperCase() + id.slice(1);
        }
      }
      setActive(current);
    };
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  return (
    <div
      style={{
        background: C.bg,
        minHeight: "100vh",
        backgroundImage: `linear-gradient(${C.grid} 1.5px, transparent 1.5px), linear-gradient(90deg, ${C.grid} 1.5px, transparent 1.5px)`,
        backgroundSize: "36px 36px",
      }}
    >
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Baloo+2:wght@600;700;800&family=Inter:wght@400;500;600;700&display=swap');
        * { box-sizing: border-box; }
        html { scroll-behavior: smooth; }
        body { margin: 0; }

        .nav-link { transition: color 0.2s ease; }
        .nav-link:hover { color: ${C.blue} !important; }

        .brutal-card { transition: transform 0.18s cubic-bezier(0.22,1,0.36,1), box-shadow 0.18s cubic-bezier(0.22,1,0.36,1); }
        .project-card:hover,
        .skills-grid > div > .brutal-card:hover,
        .achieve-grid > div > .brutal-card:hover {
          transform: translate(-3px, -3px);
          box-shadow: 9px 9px 0px ${C.ink} !important;
        }

        .skill-chip { transition: transform 0.15s ease, background 0.15s ease; display: inline-block; }
        .skill-chip:hover { transform: translateY(-2px); background: ${C.ink}; color: #fff; }

        a { transition: opacity 0.15s ease, transform 0.15s ease; }
        a:active { transform: scale(0.97); }

        .hero-art-float { animation: floatY 5s ease-in-out infinite; }
        .contact-art-float { animation: floatY 6s ease-in-out infinite 0.4s; }
        @keyframes floatY {
          0%, 100% { transform: translateY(0px); }
          50% { transform: translateY(-10px); }
        }

        .ext-link-icon { transition: transform 0.2s ease; }
        .project-card:hover .ext-link-icon { transform: translate(2px, -2px); }

        @media (prefers-reduced-motion: reduce) {
          html { scroll-behavior: auto; }
          .hero-art-float, .contact-art-float { animation: none; }
          * { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; }
        }

        @media (max-width: 860px) {
          .hero-grid { grid-template-columns: 1fr !important; }
          .hero-grid > div:last-child { order: -1; }
          .skills-grid { grid-template-columns: 1fr !important; }
          .project-grid { grid-template-columns: 1fr !important; }
          .achieve-grid { grid-template-columns: 1fr !important; }
          .contact-grid { grid-template-columns: 1fr !important; }
          .contact-grid > div:last-child { display: none; }
          .timeline { padding-left: 66px !important; }
        }
      `}</style>

      <Nav active={active} />
      <Hero />
      <About />
      <Skills />
      <Experience />
      <Education />
      <Projects />
      <Achievements />
      <Contact />
    </div>
  );
}